package com.ekayn.api.api;
import com.ekayn.api.model.User; import com.ekayn.api.repo.OrderRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/checkout") @RequiredArgsConstructor public class CheckoutStatusController { private final OrderRepository orders; @GetMapping("/status") public Map<String,Object> status(@AuthenticationPrincipal User user,@RequestParam String session_id){var order=orders.findByStripeCheckoutSessionIdAndUserId(session_id,user.getId()).orElseThrow(()->new NoSuchElementException("Commande introuvable."));return Map.of("orderId",order.getId(),"paymentStatus",order.getPaymentStatus().name(),"deliveryStatus",order.getDeliveryStatus().name());}}
